  select(LSOA21CD, cycle_infra_density_m_per_km2) |> 
  arrange(cycle_infra_density_m_per_km2)

n_zero_cycle_infra_density_m_per_km2 <- df_lsoa |> 
  filter(cycle_infra_density_m_per_km2 == 0) |> 
  count() |> 
  pull()

ggplot(df_lsoa, aes(x = cycle_infra_density_m_per_km2)) +
  geom_histogram(bins = 20, colour = "white") +
  scale_x_continuous(
    trans   = "log1p",
    breaks  = c(0, 10, 100, 500, 1500, 3000),
    labels  = scales::comma
  ) +
  labs(
    x = "Cycle infrastructure density (m/km2)",
    y = "LSOAs",
    title = str_c(
      round((n_zero_cycle_infra_density_m_per_km2/n_lsoa)*100),
      "% of LSOAs (",
      n_zero_cycle_infra_density_m_per_km2, "/", n_lsoa, 
