```{.r .cell-code}
sf_lsoa_a_roads <- sf_lsoa |>
  st_transform(4326) |>
  left_join(df_lsoa |> select(LSOA21CD, a_road_length_m), by = "LSOA21CD") |>
  mutate(
    has_a_roads = a_road_length_m > 0,
    fill_colour = if_else(has_a_roads, "#2166ac", "#ff964f")
  )

bb <- sf_lsoa_a_roads |> st_bbox()

make_basemap() |>
  fitBounds(bb[["xmin"]], bb[["ymin"]], bb[["xmax"]], bb[["ymax"]]) |>
  addPolygons(
    data = sf_lsoa_a_roads,
    fillColor = ~fill_colour,
    fillOpacity = 0.6,
    color = "white",
    weight = 0.5,
    smoothFactor = 0.5
  ) |>
  addLegend(
    position = "topright",
    colors = c("#2166ac", "#ff964f"),
    labels = c("Some A roads", "No A roads"),
    opacity = 0.6,
    title = NULL
  )
