```{.r .cell-code}
n_zero_a_road_length_m <- df_lsoa |>
  filter(a_road_length_m == 0) |>
  count() |>
  pull()

ggplot(df_lsoa, aes(x = a_road_length_m)) +
  geom_histogram(bins = 20, colour = "white") +
  scale_x_continuous(labels  = scales::comma) +
  labs(
    x = "A road length (m)",
